// hubspot-adapter (live): section 13 contract over the HubSpot CRM v3 API (private app token).
const i = $input.first().json;
const api = 'https://api.hubapi.com/crm/v3/objects/';
switch (i.op) {
  case 'find_contact':
    return [{ json: { op: i.op, method: 'POST', url: api + 'contacts/search',
      body: { filterGroups: [{ filters: [{ propertyName: 'phone', operator: 'EQ', value: i.phone }] }], properties: ['phone'], limit: 1 } } }];
  case 'create_contact':
    return [{ json: { op: i.op, method: 'POST', url: api + 'contacts', body: { properties: { phone: i.phone } } } }];
  case 'create_deal':
    return [{ json: { op: i.op, method: 'POST', url: api + 'deals', body: {
      properties: { dealname: i.name || 'WhatsApp enquiry', dealstage: i.stage, pipeline: $env.HUBSPOT_PIPELINE_ID || 'default' },
      // association type 3: deal to contact (HubSpot-defined)
      associations: [{ to: { id: String(i.contact_id) }, types: [{ associationCategory: 'HUBSPOT_DEFINED', associationTypeId: 3 }] }] } } }];
  case 'move_deal':
    return [{ json: { op: i.op, method: 'PATCH', url: api + 'deals/' + encodeURIComponent(i.deal_id || ''), body: { properties: { dealstage: i.stage } } } }];
  default:
    return [{ json: { op: i.op, invalid: true } }];
}

// Maps an HTTP status (or a network failure) to the section 13 error kinds.
function fail(kind, message) { return [{ json: { ok: false, error: { kind, message: String(message).slice(0, 300) } } }]; }
function httpFail(res, what) {
  if (!res || res.statusCode === undefined) return fail('unavailable', what + ': ' + JSON.stringify((res && res.error) || res).slice(0, 200));
  const s = res.statusCode;
  const msg = what + ' ' + s + ': ' + JSON.stringify(res.body).slice(0, 200);
  if (s === 429 || s >= 500) return fail('unavailable', msg);
  if (s === 404 || s === 410) return fail('not_found', msg);
  if (s === 409) return fail('conflict', msg);
  if (s === 401 || s === 403) return fail('unavailable', msg);
  return fail('invalid', msg);
}
const ok2xx = (res) => res && res.statusCode >= 200 && res.statusCode < 300;


const req = $('hubspot:request').first().json;
if (req.invalid) return fail('invalid', 'unknown op ' + JSON.stringify(req.op) + ' for hubspot');
const res = $input.first().json;
if (!ok2xx(res)) return httpFail(res, req.op);
const b = res.body || {};
if (req.op === 'find_contact') return [{ json: { ok: true, contact_id: (b.results && b.results[0] && String(b.results[0].id)) || null } }];
if (req.op === 'create_contact') return [{ json: { ok: true, contact_id: String(b.id) } }];
if (req.op === 'create_deal') return [{ json: { ok: true, deal_id: String(b.id) } }];
return [{ json: { ok: true } }];
